<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Cats FAQ - Everything You Need to Know</title>
    <link rel="stylesheet" href="style.css">
</head>
<body>
    <div id="root"></div>

    <script>
        // React-style component structure
        function FAQPage() {
            const faqs = [
                {
                    id: 1,
                    question: "How much should I feed my cat?",
                    answer: "Most adult cats require 200-250 calories per day, which typically translates to about 1/3 to 1/2 cup of quality dry food daily. However, caloric needs vary based on age, activity level, and metabolism. Kittens need more calories (twice as much as adults), while senior cats may need fewer. It's best to follow your food's feeding guidelines and monitor your cat's weight, adjusting portions as needed. Consult your veterinarian for personalized feeding recommendations."
                },
                {
                    id: 2,
                    question: "Why do cats purr?",
                    answer: "Cats purr for various reasons, primarily to express contentment and relaxation. However, purring doesn't always indicate happiness—cats also purr when they're stressed, anxious, or in pain. Purring is produced by the vibration of the vocal cords and serves multiple purposes: it helps kittens bond with their mother, soothes the cat's own nervous system, and can even promote healing of bones and tissues. The frequency of purring (25-150 Hz) has been shown to have therapeutic effects."
                },
                {
                    id: 3,
                    question: "How long do cats live?",
                    answer: "The average lifespan of a domestic cat is 12-18 years, though many cats live into their 20s with proper care. Indoor cats typically live longer than outdoor cats due to reduced exposure to diseases, accidents, and harsh weather. Factors affecting longevity include genetics, diet, exercise, medical care, and environmental conditions. Some of the oldest cats on record have lived into their 30s. Providing regular veterinary checkups, a balanced diet, and a safe environment can help maximize your cat's lifespan."
                },
                {
                    id: 4,
                    question: "Are cats really independent?",
                    answer: "While cats have a reputation for independence, they actually form strong bonds with their owners. Unlike dogs, cats tend to show affection in subtle ways—slow blinks, head bunts, and following you around the house. Cats are more independent than dogs in that they can entertain themselves and don't need constant attention, but they do require social interaction and can suffer from loneliness. Many cats are very affectionate with their chosen humans and may greet you at the door or sleep on your lap."
                },
                {
                    id: 5,
                    question: "What is catnip and why do cats love it?",
                    answer: "Catnip is a herb from the mint family that contains a compound called nepetalactone. When cats smell catnip, this compound triggers a response in their brain's olfactory receptors, causing playful and excited behavior. About 70-80% of cats respond to catnip, though the sensitivity is genetic—some cats are completely unaffected. Kittens under 8 weeks don't typically respond to catnip, and cats can develop a tolerance if exposed too frequently. The effects usually last about 10-15 minutes."
                },
                {
                    id: 6,
                    question: "How can I keep my indoor cat entertained?",
                    answer: "Indoor cats need mental and physical stimulation to stay healthy and happy. Provide interactive toys like feather wands, laser pointers, and balls. Puzzle feeders and treat-dispensing toys engage their problem-solving skills. Cat trees and window perches satisfy their climbing instinct and provide entertainment from bird watching. Rotate toys to maintain interest and dedicate 15-30 minutes daily to interactive play. Consider training your cat to walk on a leash, providing controlled outdoor time. Some cats enjoy playing fetch or learning tricks with positive reinforcement."
                },
                {
                    id: 7,
                    question: "Why do cats knock things off tables?",
                    answer: "Cats knock things off tables for several reasons. First, it's a form of play and exercise—they're testing their hunting and pouncing skills on moving objects. Second, it's a way to get your attention, especially if they're bored or seeking interaction. Third, cats are naturally curious and may be exploring objects to understand their properties. Cats also have a behavior called 'paw batting' where they test whether objects are alive or might be prey. While frustrating, it's normal feline behavior and can be redirected to appropriate toys."
                },
                {
                    id: 8,
                    question: "What's the best litter box setup?",
                    answer: "The general rule is to have one litter box per cat, plus one extra. Boxes should be placed in quiet, easily accessible locations away from food and water bowls. Size matters—boxes should be 1.5 times the length of your cat from nose to tail. Choose unscented, fine-grained litter as cats prefer this texture. Scoop daily and completely change litter weekly. Some cats prefer covered boxes for privacy, while others feel trapped by them. If you have multiple cats, separate boxes prevent territorial issues. Try different litter types to find your cat's preference."
                }
            ];

            return `
                <div class="faq-container">
                    <header class="faq-header">
                        <h1>Cat FAQ</h1>
                        <p class="subtitle">Everything You Need to Know About Your Feline Friend</p>
                    </header>

                    <main class="faq-content">
                        ${faqs.map(faq => FAQItem(faq)).join('')}
                    </main>
                </div>
            `;
        }

        function FAQItem(faq) {
            return `
                <div class="example">
                    <button class="faq-question" data-id="${faq.id}" aria-expanded="false">
                        <span class="question-text">${faq.question}</span>
                        <span class="toggle-icon">+</span>
                    </button>
                    <div class="details" id="answer-${faq.id}" hidden>
                        <div class="faq-answer">
                            ${faq.answer}
                        </div>
                    </div>
                </div>
            `;
        }

        // Render the app
        const root = document.getElementById('root');
        root.innerHTML = FAQPage();

        // Setup event listeners
        document.querySelectorAll('.faq-question').forEach(button => {
            button.addEventListener('click', function() {
                const id = this.dataset.id;
                const detailsDiv = document.getElementById(`answer-${id}`);
                const isExpanded = this.getAttribute('aria-expanded') === 'true';

                // Close all other open items
                document.querySelectorAll('.faq-question').forEach(btn => {
                    if (btn !== this && btn.getAttribute('aria-expanded') === 'true') {
                        btn.setAttribute('aria-expanded', 'false');
                        btn.querySelector('.toggle-icon').textContent = '+';
                        document.getElementById(`answer-${btn.dataset.id}`).hidden = true;
                    }
                });

                // Toggle current item
                this.setAttribute('aria-expanded', !isExpanded);
                this.querySelector('.toggle-icon').textContent = isExpanded ? '+' : '−';
                detailsDiv.hidden = isExpanded;
            });
        });
    </script>
    <link rel="stylesheet" href="style.css">
</body>
</html>
